document.querySelectorAll('form[data-print-form]').forEach((form)=>{form.addEventListener('submit',()=>{const next=form.dataset.thanks;if(next){let redirect=form.querySelector('input[name="_next"]');if(!redirect){redirect=document.createElement('input');redirect.type='hidden';redirect.name='_next';form.appendChild(redirect)}redirect.value=new URL(next,window.location.href).href}})});document.querySelectorAll('.menu-toggle').forEach((button)=>{button.addEventListener('click',()=>{const header=button.closest('.header');const open=header.classList.toggle('menu-open');button.setAttribute('aria-expanded',String(open))})});document.addEventListener('click',(event)=>{if(!event.target.closest('.header'))document.querySelectorAll('.header.menu-open').forEach((header)=>{header.classList.remove('menu-open');header.querySelector('.menu-toggle')?.setAttribute('aria-expanded','false')})});
